CREATE TABLE plexus_atlas.atlas_airports (`id` String, `name` String, `municipality` String, `iata` String, `latitude` Float64, `longitude` Float64, `scheduled` Bool, `kind` String, `ordinal` UInt32) ENGINE = MergeTree ORDER BY id SETTINGS allow_nullable_key = 1, index_granularity = 1024;

