CREATE TABLE plexus_atlas.atlas_economy (`region_id` String, `company_rows` Nullable(Int64), `strict_rows` Nullable(Int64), `strict_revenue_rub` Nullable(Float64), `fns_matched_rows` Nullable(Int64), `ordinal` UInt32) ENGINE = MergeTree ORDER BY region_id SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_exported_indices (`region_id` String, `scenario` String, `hansen` Nullable(Float64), `covered_population` Nullable(Int64), `total_population` Nullable(Int64), `covered_settlements` Nullable(Int64), `total_settlements` Nullable(Int64), `model_version` Nullable(String), `artifact_version` Nullable(String), `hansen_1h` Nullable(Float64), `hansen_2h` Nullable(Float64), `hansen_4h` Nullable(Float64), `ordinal` UInt32) ENGINE = MergeTree ORDER BY (scenario, region_id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

