CREATE TABLE plexus_atlas.atlas_links (`id` String, `region_id` String, `mode` String, `season` Nullable(String), `from_id` String, `from_name` String, `to_id` String, `to_name` String, `km` Nullable(Float64), `freq_per_week` Nullable(Float64), `freq_note` Nullable(String), `vehicle` Nullable(String), `confidence` Nullable(String), `source_url` Nullable(String), `source_date` Nullable(String), `is_model` Bool, `ordinal` UInt32) ENGINE = MergeTree ORDER BY (region_id, mode, season, id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_metadata (`key` String, `value` String, `ordinal` UInt32) ENGINE = MergeTree ORDER BY key SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_points (`id` String, `name` String, `region_id` String, `lat` Float64, `lon` Float64, `x` Float64, `y` Float64, `ordinal` UInt32) ENGINE = MergeTree ORDER BY (region_id, id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_regions (`id` String, `name` String, `settlements` Int64, `population` Int64, `ordinal` UInt32) ENGINE = MergeTree ORDER BY id SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_settlements (`id` String, `name` String, `region_id` String, `population` Nullable(Int64), `x` Nullable(Float64), `y` Nullable(Float64), `companies` Nullable(Int64), `revenue_rub` Nullable(Float64), `ordinal` UInt32, `name_key` String MATERIALIZED trimBoth(replaceRegexpAll(replaceAll(lowerUTF8(name), 'ё', 'е'), '[\\s\\p{Z}]+', ' ')), INDEX place_name name_key TYPE ngrambf_v1(3, 8192, 3, 0) GRANULARITY 1) ENGINE = MergeTree ORDER BY (region_id, id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_shapes (`id` String, `name` String, `path` String, `path_low` Nullable(String), `ordinal` UInt32) ENGINE = MergeTree ORDER BY id SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_sources (`id` String, `title` String, `period` Nullable(String), `url` Nullable(String), `note` Nullable(String), `rows` Nullable(Int64), `ordinal` UInt32) ENGINE = MergeTree ORDER BY (id, ordinal) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.atlas_winter_roads (`district` Nullable(String), `route` Nullable(String), `road_km` Nullable(Float64), `opening_date` Nullable(String), `closure_date` Nullable(String), `weight_limit_tonnes` Nullable(Float64), `season_end_year` Nullable(Int64), `report_date` Nullable(String), `source_file` Nullable(String), `ordinal` UInt32) ENGINE = MergeTree ORDER BY ordinal SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_atlas.documents (`path` String, `sha256` String, `body` String) ENGINE = MergeTree ORDER BY path SETTINGS index_granularity = 8192;

CREATE VIEW plexus_atlas.links (`source` String, `id` String, `record` String) AS SELECT path AS source, JSONExtractString(record, 'id') AS id, record FROM plexus_atlas.documents ARRAY JOIN JSONExtractArrayRaw(body, 'links') AS record WHERE path IN ('atlas.json', 'network-links.json');

CREATE TABLE plexus_atlas.migrated_sources (`path` String, `sha256` String, `bytes` UInt64) ENGINE = MergeTree ORDER BY path SETTINGS index_granularity = 8192;

CREATE VIEW plexus_atlas.points (`source` String, `id` String, `record` String) AS SELECT path AS source, JSONExtractString(record, 'id') AS id, record FROM plexus_atlas.documents ARRAY JOIN JSONExtractArrayRaw(body, 'points') AS record WHERE path IN ('atlas.json', 'network-links.json');

CREATE VIEW plexus_atlas.regions (`source` String, `id` String, `record` String) AS SELECT path AS source, JSONExtractString(record, 'id') AS id, record FROM plexus_atlas.documents ARRAY JOIN JSONExtractArrayRaw(body, 'regions') AS record WHERE path IN ('atlas.json', 'network-links.json');

