CREATE TABLE plexus_casechamp.market_cities (`city` Nullable(String), `oktmo` Nullable(String), `region` Nullable(String), `is_capital` Nullable(Bool), `population` Nullable(Int64), `lat` Nullable(Float64), `lon` Nullable(Float64), `node` Nullable(Int64), `snap_h` Nullable(Float64)) ENGINE = MergeTree ORDER BY region SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.mart_mo (`oktmo` Nullable(String), `region` Nullable(String), `mo_name` Nullable(String), `population` Nullable(Int32), `n_settlements` Nullable(Int64), `n_small` Nullable(Int64), `pop_small` Nullable(Int128), `no_regular_transport_pct` Nullable(Float64), `no_regular_transport_year` Nullable(Int64), `roads_substandard_pct` Nullable(Float64), `roads_local_km` Nullable(Float64)) ENGINE = MergeTree ORDER BY region SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.mart_region (`region` Nullable(String), `population` Nullable(Int128), `pop_no_transport` Nullable(Float64), `roads_substandard_pct_w` Nullable(Float64), `n_settlements` Nullable(Int128), `n_small` Nullable(Int128), `pop_small` Nullable(Int128), `mo_with_data` Nullable(Int64), `mo_total` Nullable(Int64), `share_no_transport` Nullable(Float64), `share_small_np` Nullable(Float64), `roads_krub_2020` Nullable(Float64), `transport_krub_2020` Nullable(Float64), `total_krub_2020` Nullable(Float64), `roads_rub_per_capita_2020` Nullable(Float64), `capital` Nullable(String), `cap_road_links` Nullable(Int64), `cap_rail_links` Nullable(Int64), `cap_air_direct` Nullable(Int64)) ENGINE = MergeTree ORDER BY region SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.np_access (`season` Nullable(String), `point_id` Nullable(String), `name` Nullable(String), `region` Nullable(String), `mun_upper` Nullable(String), `population` Nullable(Int32), `is_dc` Nullable(Bool), `on_road` Nullable(Bool), `manual_only` Nullable(Bool), `snap_km` Nullable(Float64), `t_district_center_h` Nullable(Float64), `dc_is_own` Nullable(Bool), `t_capital_h` Nullable(Float64), `t_capital_best_h` Nullable(Float64), `nearest_city` Nullable(String), `t_nearest_city_h` Nullable(Float32), `t_centre_1k_h` Nullable(Float64), `t_centre_5k_h` Nullable(Float64), `t_centre_18k_h` Nullable(Float64), `no_all_season_road` Nullable(Bool)) ENGINE = MergeTree ORDER BY (region, point_id) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.np_city_times (`season` Nullable(String), `point_id` Nullable(String), `city` Nullable(String), `road_h` Nullable(Float32), `best_h` Nullable(Float32)) ENGINE = MergeTree ORDER BY (season, point_id, city) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.od_multimodal (`season` Nullable(String), `wait` Nullable(String), `from_id` Nullable(String), `to_id` Nullable(String), `hours` Nullable(Float64), `km` Nullable(Float64), `uses_air` Nullable(Bool), `uses_seasonal` Nullable(Bool)) ENGINE = MergeTree ORDER BY tuple() SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.od_road (`from_id` Nullable(String), `to_id` Nullable(String), `road_h` Nullable(Float64), `road_km` Nullable(Float64)) ENGINE = MergeTree ORDER BY tuple() SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.road_ways (`way_id` Nullable(Int64), `class` Nullable(String), `ref` Nullable(String), `name` Nullable(String), `surface` Nullable(String), `speed_kmh` Nullable(Float64), `length_km` Nullable(Float64), `is_bridge` Nullable(Bool), `is_ferry` Nullable(Bool), `is_seasonal` Nullable(Bool), `lat_mid` Nullable(Float64), `lon_mid` Nullable(Float64)) ENGINE = MergeTree ORDER BY tuple() SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.stg_bdmo (`metric` Nullable(String), `region_name` Nullable(String), `municipality` Nullable(String), `mun_level` Nullable(String), `oktmo` Nullable(String), `year` Nullable(Int64), `value` Nullable(Float64)) ENGINE = MergeTree ORDER BY tuple() SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.stg_intercity (`city_from` Nullable(String), `region_from` Nullable(String), `oktmo_from` Nullable(String), `is_capital_from` Nullable(Bool), `population_from` Nullable(Int64), `lat_from` Nullable(Float64), `lon_from` Nullable(Float64), `city_to` Nullable(String), `region_to` Nullable(String), `oktmo_to` Nullable(String), `is_capital_to` Nullable(Bool), `population_to` Nullable(Int64), `lat_to` Nullable(Float64), `lon_to` Nullable(Float64), `transport_type` Nullable(String), `distance_km` Nullable(Float64), `distance_hr` Nullable(Float64), `missing_reason` Nullable(String), `source` Nullable(String)) ENGINE = MergeTree ORDER BY (region_from, city_from) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.stg_settlements (`object_level` Nullable(String), `object_name` Nullable(String), `oktmo` Nullable(String), `region` Nullable(String), `mun_upper` Nullable(String), `mun_lower` Nullable(String), `settlement` Nullable(String), `population` Nullable(Int32), `latitude` Nullable(Float64), `longitude` Nullable(Float64)) ENGINE = MergeTree ORDER BY (region, oktmo) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_casechamp.tuva_points (`point_id` Nullable(String), `name` Nullable(String), `mun_upper` Nullable(String), `population` Nullable(Int64), `lat` Nullable(Float64), `lon` Nullable(Float64), `kind` Nullable(String), `is_district_center` Nullable(Bool), `snap_km` Nullable(Float64), `on_road` Nullable(Bool)) ENGINE = MergeTree ORDER BY point_id SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_graph.edges (`src` Nullable(Int32), `dst` Nullable(Int32), `h` Nullable(Float32), `km` Nullable(Float32), `way_idx` Nullable(Int32)) ENGINE = MergeTree ORDER BY (way_idx, src, dst) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_graph.locations (`point_id` Nullable(String), `settlement` Nullable(String), `region` Nullable(String), `node` Nullable(Int64), `lon` Nullable(Float64), `lat` Nullable(Float64), `snap_km` Nullable(Float64), `population` Nullable(Int32), INDEX place_name lowerUTF8(ifNull(settlement, '')) TYPE ngrambf_v1(3, 8192, 3, 0) GRANULARITY 1) ENGINE = MergeTree ORDER BY (region, point_id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_graph.nodes (`node` Nullable(Int32), `osm_node` Nullable(Int64), `lat` Nullable(Float64), `lon` Nullable(Float64), `comp` Nullable(Int32)) ENGINE = MergeTree ORDER BY node SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_graph.points (`point_id` Nullable(String), `region` Nullable(String), `lat` Nullable(Float64), `lon` Nullable(Float64), `population` Nullable(Int32), `snap_km` Nullable(Float64), `on_road` Nullable(Bool), `node` Nullable(Int64), `comp` Nullable(Int32), PROJECTION by_point (SELECT point_id, node, snap_km ORDER BY point_id)) ENGINE = MergeTree ORDER BY (region, point_id) SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_graph.region_codes (`oktmo` Nullable(String), `region` Nullable(String)) ENGINE = MergeTree ORDER BY oktmo SETTINGS allow_nullable_key = 1, index_granularity = 256;

CREATE TABLE plexus_graph.region_points (`region` Nullable(String), `season` Nullable(String), `point_id` Nullable(String), `population` Nullable(Int32), `node` Nullable(Int64), `snap_km` Nullable(Float64)) ENGINE = MergeTree ORDER BY (region, season, point_id) SETTINGS allow_nullable_key = 1, index_granularity = 1024;

CREATE TABLE plexus_graph.road_lines (`way_id` Int64, `name` String, `highway` LowCardinality(String), `speed_kmh` Float64, `source_node` Int64, `target_node` Int64, `coordinates` Array(Array(Float64)), `rank` UInt8, `min_lon` Float64, `max_lon` Float64, `min_lat` Float64, `max_lat` Float64, `edge_count` UInt32, INDEX bounds_lon_min min_lon TYPE minmax GRANULARITY 1, INDEX bounds_lon_max max_lon TYPE minmax GRANULARITY 1, INDEX bounds_lat_min min_lat TYPE minmax GRANULARITY 1, INDEX bounds_lat_max max_lat TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY (rank, floor(min_lon), floor(min_lat), way_id) SETTINGS index_granularity = 2048;

CREATE TABLE plexus_graph.road_lookup (`lookup` String, `ref` String) ENGINE = MergeTree ORDER BY (lookup, ref) SETTINGS index_granularity = 256;

CREATE TABLE plexus_graph.ways (`way_id` Nullable(Int64), `highway` Nullable(String), `ref` Nullable(String), `name` Nullable(String), `surface` Nullable(String), `tracktype` Nullable(String), `oneway` Nullable(String), `is_bridge` Nullable(Bool), `is_ferry` Nullable(Bool), `is_seasonal` Nullable(Bool), `way_idx` Nullable(Int32), `speed_kmh` Nullable(Float64), `km` Nullable(Float64), PROJECTION by_osm_id (SELECT way_id, way_idx ORDER BY way_id), PROJECTION by_reference (SELECT way_idx, way_id, name, ref, km ORDER BY ref)) ENGINE = MergeTree ORDER BY way_idx SETTINGS allow_nullable_key = 1, index_granularity = 8192;

CREATE TABLE plexus_scenario.catalog (`model_version` String, `artifact_version` String, `seasons` Array(String), `normalization_base` Float64, `assumptions` Array(String)) ENGINE = MergeTree ORDER BY artifact_version SETTINGS index_granularity = 8192;

CREATE TABLE plexus_scenario.cities (`ordinal` UInt32, `id` String, `region` String, `population` Float64, `latitude` Float64, `longitude` Float64, `is_capital` Bool) ENGINE = MergeTree ORDER BY ordinal SETTINGS index_granularity = 8192;

CREATE TABLE plexus_scenario.city_times (`season` String, `from_idx` UInt32, `to_idx` UInt32, `best_h` Float64) ENGINE = MergeTree ORDER BY (season, from_idx, to_idx) SETTINGS index_granularity = 8192;

CREATE TABLE plexus_scenario.points (`season` String, `point_idx` UInt32, `population` Float64, `region_idx` Int32) ENGINE = MergeTree ORDER BY (season, point_idx) SETTINGS index_granularity = 8192;

CREATE TABLE plexus_scenario.regions (`ordinal` UInt32, `region_id` String, `name` String) ENGINE = MergeTree ORDER BY ordinal SETTINGS index_granularity = 8192;

CREATE TABLE plexus_scenario.times (`season` String, `point_idx` UInt32, `city_idx` UInt32, `road_h` Float32, `best_h` Float32) ENGINE = MergeTree ORDER BY (season, point_idx, city_idx) SETTINGS index_granularity = 8192;

CREATE TABLE plexus_state.analysis_details (`analysis_id` String, `way_id` Int64, `detail` Tuple(result Tuple(candidate Tuple(way_id Int64, name String, length_km Float64, score Float64, isolation_score Float64, crosses_boundary Bool), before Float64, after Float64, delta Float64, affected_population Int64, isolated_population Int64, elapsed_seconds Float64), lines Array(Array(Array(Float64))), settlements Array(Tuple(impact Tuple(point_id String, population Int64, before Float64, after Float64, delta Float64, newly_isolated Bool, affected Bool), name String, longitude Float64, latitude Float64))), `updated` UInt64) ENGINE = ReplacingMergeTree(updated) ORDER BY (analysis_id, way_id) SETTINGS index_granularity = 256;

CREATE TABLE plexus_state.analysis_jobs (`id` String, `job` Tuple(id String, region_id String, region String, mode String, percent Int64, fingerprint String, status String, stage String, candidates Array(Tuple(way_id Int64, name String, length_km Float64, score Float64, isolation_score Float64, crosses_boundary Bool)), results Array(Tuple(candidate Tuple(way_id Int64, name String, length_km Float64, score Float64, isolation_score Float64, crosses_boundary Bool), before Float64, after Float64, delta Float64, affected_population Int64, isolated_population Int64, elapsed_seconds Float64)), failures Array(Tuple(way_id Int64, code String)), candidate_count Int64, batch_target Int64, current_way_id Nullable(Int64), completed Int64, total Int64, elapsed_seconds Float64, error Nullable(String), compatible Bool), `boundary` Tuple(id String, name String, bounds Tuple(Float64, Float64, Float64, Float64), polygons Array(Array(Array(Tuple(Float64, Float64))))), `updated` UInt64) ENGINE = ReplacingMergeTree(updated) ORDER BY id SETTINGS index_granularity = 256;

CREATE TABLE plexus_state.road_jobs (`id` String, `region_id` String, `region` String, `scenario` String, `changes` Array(Tuple(way_id Int64, speed_factor Float64)), `status` String, `completed` Int64, `total` Int64, `version` String, `result` Array(Tuple(before Float64, after Float64, delta Float64, relative_percent Nullable(Float64), population Int64, settlements Int64, changed_edges Int64, normalization Float64, elapsed_seconds Float64, affected_settlements Nullable(Int64), money Array(Tuple(before_hours Float64, after_hours Float64, hours_saved_per_trip Float64, annual_hours_saved Float64, annual_gross_rub Float64, annual_net_rub Float64, simple_payback_years Nullable(Float64), assumptions Tuple(origin_point_id String, market_city String, trips_per_year Float64, rub_per_hour Float64, capital_cost_rub Float64, annual_operating_cost_rub Float64), method String)), routing_method String, settlement_effects Array(Tuple(point_id String, before Float64, after Float64, delta Float64)))), `error` Nullable(String), `addition` Array(Tuple(source_node Int64, target_node Int64, travel_hours Float64, coordinates Array(Array(Array(Float64))))), `money_assumptions` Array(Tuple(origin_point_id String, market_city String, trips_per_year Float64, rub_per_hour Float64, capital_cost_rub Float64, annual_operating_cost_rub Float64)), `updated` UInt64) ENGINE = ReplacingMergeTree(updated) ORDER BY id SETTINGS index_granularity = 256;
